// Place lookup backed by OpenStreetMap Nominatim.
// Public, key-less endpoint — usage policy caps us at ~1 request/second, so
// callers must debounce and reuse the in-memory cache below.

import { logError } from '@/utils/logger';

const NOMINATIM_SEARCH_URL = 'https://nominatim.openstreetmap.org/search';
const MAX_RESULTS = 8;
const MIN_QUERY_LENGTH = 3;
const CACHE_LIMIT = 50;

export interface PlaceSuggestion {
    /** Stable key for React lists. */
    id: string;
    /** Full human-readable place string, stored as the form's location value. */
    label: string;
    /** Leading token of the label (e.g. "Sitamarhi"). */
    primary: string;
    /** Remainder of the label (e.g. "Bihar, India"). */
    secondary: string;
    latitude: number;
    longitude: number;
}

interface NominatimPlace {
    place_id: number;
    display_name: string;
    name?: string;
    lat: string;
    lon: string;
}

const cache = new Map<string, PlaceSuggestion[]>();

function toSuggestion(place: NominatimPlace): PlaceSuggestion {
    const label = place.display_name ?? '';
    const parts = label.split(',').map((p) => p.trim()).filter(Boolean);
    const primary = place.name?.trim() || parts[0] || label;
    const secondary = parts.slice(1).join(', ');

    return {
        id: String(place.place_id),
        label,
        primary,
        secondary,
        latitude: Number.parseFloat(place.lat),
        longitude: Number.parseFloat(place.lon),
    };
}

/**
 * Searches places matching `query`. Returns an empty list for short queries,
 * aborted requests, or provider failures — never throws.
 */
export async function searchPlaces(query: string, signal?: AbortSignal): Promise<PlaceSuggestion[]> {
    const trimmed = query.trim();
    if (trimmed.length < MIN_QUERY_LENGTH) return [];

    const cacheKey = trimmed.toLowerCase();
    const cached = cache.get(cacheKey);
    if (cached) return cached;

    const url = `${NOMINATIM_SEARCH_URL}?format=jsonv2&addressdetails=0&limit=${MAX_RESULTS}&q=${encodeURIComponent(trimmed)}`;

    try {
        const response = await fetch(url, {
            signal,
            headers: { Accept: 'application/json' },
        });
        if (!response.ok) return [];

        const data = (await response.json()) as NominatimPlace[];
        const suggestions = data
            .map(toSuggestion)
            .filter((s) => Number.isFinite(s.latitude) && Number.isFinite(s.longitude));

        if (cache.size >= CACHE_LIMIT) {
            const oldest = cache.keys().next().value;
            if (oldest !== undefined) cache.delete(oldest);
        }
        cache.set(cacheKey, suggestions);

        return suggestions;
    } catch (error) {
        if ((error as Error)?.name === 'AbortError') return [];
        logError('geocoding', 'Place search failed', error);
        return [];
    }
}

export const GeocodingServices = { searchPlaces };
